import{_ as s,o as t,c as a,a4 as i}from"./chunks/framework.DA9C4Pbl.js";const g=JSON.parse('{"title":"Rotating the Postgres password on an existing self-hosted install","description":"","frontmatter":{"title":"Rotating the Postgres password on an existing self-hosted install","visibility":"public","audience":"operator","tier":"guide","source":"handwritten"},"headers":[],"relativePath":"guides/operating/rotate-postgres-password.md","filePath":"guides/operating/rotate-postgres-password.md"}'),o={name:"guides/operating/rotate-postgres-password.md"};function n(d,e,r,h,l,c){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="rotating-the-postgres-password-on-an-existing-self-hosted-install" tabindex="-1">Rotating the Postgres password on an existing self-hosted install <a class="header-anchor" href="#rotating-the-postgres-password-on-an-existing-self-hosted-install" aria-label="Permalink to “Rotating the Postgres password on an existing self-hosted install”">​</a></h1><p>Until version 3.10, <code>arcsecond setup</code> wrote a default Postgres password (<code>arcsecond_docker</code>) into <code>.env</code>. New installs generate a per-install random password automatically, but <strong>existing installs keep the original weak password until you rotate it</strong> — Postgres only reads <code>POSTGRES_PASSWORD</code> at first container boot to bootstrap the role, so changing the value in <code>.env</code> after the fact does nothing on its own.</p><p>One command rotates it in the three places that must agree: the live database role, the <code>.env</code> file, and the running containers. Run it in the Arcsecond folder (or from anywhere, once <code>arcsecond setup</code> has run on this machine), with the installation running:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-password</span></span></code></pre></div><p>It generates a strong random password, checks that the current credentials in <code>.env</code> work before touching anything, backs <code>.env</code> up beside itself, changes the role&#39;s password in the database, rewrites <code>POSTGRES_PASSWORD</code>, verifies the new password against the database, and recreates the <code>backend</code>, <code>worker</code> and <code>beat</code> containers (and <code>alerts</code> if you have it) so they pick it up. The <code>db</code> container is left alone: its password lives in the volume, and recreating it would be downtime for nothing.</p><p>If the new password does not verify, the command puts the database and <code>.env</code> back the way they were, and says so.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to “Options”">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>--show</code></td><td>print the new password, instead of only writing it to <code>.env</code></td></tr><tr><td><code>--password &lt;value&gt;</code></td><td>set this password rather than a generated one — letters, digits and <code>. _ ~ -</code> only, 16 characters minimum</td></tr><tr><td><code>--no-restart</code></td><td>change the database and <code>.env</code> but leave the containers running with the old password until you run <code>arcsecond restart</code> yourself</td></tr><tr><td><code>--dry-run</code></td><td>show what would happen, change nothing</td></tr></tbody></table><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to “Verify”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span></span></code></pre></div><p>A backend that is <code>running</code> and <code>healthy</code> in <code>arcsecond status</code>, with no authentication error in its last lines, is done. Delete the <code>.env.bak-…</code> file once you have confirmed the stack is healthy — it still holds the old password.</p><h2 id="file-permissions" tabindex="-1">File permissions <a class="header-anchor" href="#file-permissions" aria-label="Permalink to “File permissions”">​</a></h2><p>While you&#39;re at it, lock <code>.env</code> down so other local users can&#39;t read it:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p>The file holds the Postgres password, the Django <code>SECRET_KEY</code>, the field encryption key, and the JWT signing keys. None of them are useful to an attacker on their own, but defense in depth is cheap.</p>`,15)])])}const k=s(o,[["render",n]]);export{g as __pageData,k as default};
